--- from: Assets/BundleResources/Prefabs/RegressionNew/RegressionNewDailyPanel5010.prefab > name: RegressionNewDailyPanel5010
---@class RegressionNewDailyPanel
---@field Env                           	RegressionNewDailyPanel                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Content                       	UnityEngine.RectTransform               	@ 0    
---@field RewardNode                    	UnityEngine.RectTransform               	@ 1    
---@field BigReward                     	UnityEngine.RectTransform               	@ 2    
local RegressionNewDailyPanel = Class('RegressionNewDailyPanel')
local SignCellPath = "Game.Activity.RegressionActivity.Cell.RegressionNewDailyCellNode"
---@type RegressionUtils
local RegressionUtils = import('Game.Activity.RegressionActivity.RegressionUtils')

function RegressionNewDailyPanel:__init()
	self.signEnv = {}
	self.signVos = nil
end

function RegressionNewDailyPanel:__delete()
	self.signEnv = {}
	self.signVos = nil
end

function RegressionNewDailyPanel:Awake()
	self:InitEnv()
end

function RegressionNewDailyPanel:InitEnv()
	local env = CfUtils.GetLuaScr(self.RewardNode, SignCellPath)
	if env then
		table.insert(self.signEnv,env)
	end
end

function RegressionNewDailyPanel:RefreshTopGoods()
	CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId})
end

function RegressionNewDailyPanel:Refresh(config)
	self.config = config
	self.dojo = RegressionUtils.GetRegressHomeDojo()
	local data = self.dojo:GetDailySignInfo()
	local vos = data.loginList
	local count = table.count(vos)
	for i = 1, count - 1 do
		local env = self.signEnv[i]
		if isNull(env) then
			local go = CfUtils.InstantiateGo(self.RewardNode,self.Content,false)
			if go then
				env = CfUtils.GetLuaScr(go, SignCellPath)
				table.insert(self.signEnv,env)
			end
		end
		env:SetBtnCallBack(Bind(self,self.OnSignClick))
		env:FreshBaseUI(vos[i], i)
	end
	
	local bigRewardEnv = self.signEnv[count]
	if isNull(bigRewardEnv) then
		bigRewardEnv = CfUtils.GetLuaScr(self.BigReward,SignCellPath)
		if isNotNull(bigRewardEnv) then
			self.signEnv[count] = bigRewardEnv
		end
	end
	bigRewardEnv:SetBtnCallBack(Bind(self,self.OnSignClick))
	bigRewardEnv:FreshBaseUI(vos[count], count)
end

function RegressionNewDailyPanel:GetVosByGroupId(groupId)
	if isNull(self.signVos) then
		local allVos = CfUtils.GetCf(AutoIds.IdSetting6506,"RegressionSignVo",true)
		local data = {}
		for i, v in pairs(allVos) do
			if v.group == groupId then
				table.insert(data,v)
			end
		end
		table.sort(data,function(a,b)
			return a.day < b.day
		end)
		self.signVos = data
	end
	return self.signVos
end

function RegressionNewDailyPanel:OnSignClick(day,index)
	GameUtils.Request(Interfaces.NewRegressDrawLoginReward,{day = day},function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = response.data
			self.signEnv[index]:SetStates(Constants.GetStatus.Has)
			self.signEnv[index]:RefreshStatus()
			RegressionUtils.RefreshRedPoint(self.config.type)
			if table.count(responseData.rewards) > 0 then
				GoodsUtils.DrawRewards(responseData.rewards,true)
				CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards }} )
			end
		end
	end)
end

function RegressionNewDailyPanel:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return RegressionNewDailyPanel